    "C", "ST", "L", "O", "OU", "CN", "emailAddress", "serialNumber",
    "street", "postalCode", "givenName", "surname", "title", "GN", "SN",
    "DC", "UID"
]

SAFE_VALUE_CHARS = string.ascii_letters + string.digits + " .-_@"  # avoid ',' and '='

COUNTRY_CODES = [
    "US", "GB", "DE", "FR", "JP", "CN", "IN", "CA", "AU", "BR", "KR",
    "SE", "NL", "CH", "IT", "ES"
]

DOMAINS = [
    "example.com", "test.local", "fuzz.invalid", "mbedtls.test", "example.org",
    "corp.example", "lab.internal"
]

ORG_WORDS = [
    "Example", "Fuzzer", "Security", "Research", "Testing", "Systems",
    "Solutions", "Labs", "Networks", "Services"
]

OU_WORDS = ["Engineering", "QA", "DevOps", "R&D", "IT", "Compliance", "Support"]

CNS = [
    "server", "client", "api", "gateway", "db", "mail", "vpn", "auth",
    "web", "device"
]

def _rand_choice(rng: random.Random, items: List[str]) -> str:
    return items[rng.randrange(0, len(items))]


def _rand_token(rng: random.Random, min_len: int, max_len: int) -> str:
    n = rng.randint(min_len, max_len)
    return ''.join(rng.choice(SAFE_VALUE_CHARS) for _ in range(n)).strip()


def _rand_country(rng: random.Random) -> str:
    # 2-letter country
    if rng.random() < 0.8:
        return _rand_choice(rng, COUNTRY_CODES)
    # Occasionally generate random two-letter uppercase
    return ''.join(rng.choice(string.ascii_uppercase) for _ in range(2))


def _rand_domain(rng: random.Random) -> str:
    if rng.random() < 0.7:
        return _rand_choice(rng, DOMAINS)
    # Compose domain
    label = _rand_token(rng, 3, 10).lower().replace(' ', '-')
    tld = _rand_choice(rng, ["com", "org", "net", "local", "invalid", "test"])
    return f"{label}.{tld}"


def _rand_org(rng: random.Random) -> str:
    words = [
        _rand_choice(rng, ORG_WORDS),
        _rand_choice(rng, ORG_WORDS)
    ]
    if rng.random() < 0.4:
        words.append(_rand_choice(rng, ORG_WORDS))
    return (" ".join(words)).replace('  ', ' ')


def _rand_ou(rng: random.Random) -> str:
    return _rand_choice(rng, OU_WORDS)


def _rand_cn(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return f"{_rand_choice(rng, CNS)}.{_rand_domain(rng)}"
    return _rand_token(rng, 3, 32)


def _rand_email(rng: random.Random) -> str:
    user = _rand_token(rng, 3, 16).lower().replace(' ', '')
