    if attr == "DC":
        # domain component: labels only letters/digits/hyphen
        return _rand_token(rng, 2, 10).lower().replace(' ', '-')
    if attr == "UID":
        return _rand_token(rng, 4, 12)
    # Fallback safe token
    return _rand_token(rng, 3, 16)


def _make_rdn(rng: random.Random, allow_multi: bool) -> str:
    # Choose an attribute
    attr = _rand_choice(rng, ATTR_TYPES_COMMON)
    value = _val_for_attr(rng, attr)
    rdn = f"{attr}={value}"
    # Occasionally create a multi-valued RDN using '+'
    if allow_multi and rng.random() < 0.2:
        # add one more attribute distinct from the first
        attr2 = _rand_choice(rng, [a for a in ATTR_TYPES_COMMON if a != attr])
        value2 = _val_for_attr(rng, attr2)
        rdn += f"+{attr2}={value2}"
    return rdn


def _build_dn(rng: random.Random) -> str:
    # Ensure a sensible base: include C, O, and CN with high probability
    rdns: List[str] = []
    if rng.random() < 0.9:
        rdns.append(f"C={_rand_country(rng)}")
    if rng.random() < 0.85:
        rdns.append(f"O={_rand_org(rng)}")
    # Add between 1 and 5 additional RDNs (may include CN)
    count = rng.randint(1, 5)
    for _ in range(count):
        rdns.append(_make_rdn(rng, allow_multi=True))
    # Guarantee at least one CN
    if not any(r.startswith("CN=") or "+CN=" in r for r in rdns):
        rdns.append(f"CN={_rand_cn(rng)}")
    # Shuffle order (order is significant; variety helps)
    rng.shuffle(rdns)
    dn = ",".join(rdns)
    # Truncate to keep within reasonable size expected by stubs (<= 256 often)
    if len(dn) > 512:
        dn = dn[:512]
        # Avoid cutting in the middle of an escape; our characters avoid escapes, so safe
        # Ensure not ending with a dangling backslash or incomplete RDN component
        while dn and dn[-1] in ['\\', '+', ',', '=']:
            dn = dn[:-1]
    return dn


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly pick between several DN patterns to diversify inputs across calls
    mode = rng.randint(0, 4)
    if mode == 0:
        # Minimal common DN
        dn = f"C={_rand_country(rng)},O={_rand_org(rng)},CN={_rand_cn(rng)}"
    elif mode == 1:
        # With email and OU
        dn = f"C={_rand_country(rng)},O={_rand_org(rng)},OU={_rand_ou(rng)},CN={_rand_cn(rng)},emailAddress={_rand_email(rng)}"
    elif mode == 2:
        # Directory-style with ST, L, street, postalCode
        dn = (
            f"C={_rand_country(rng)},ST={_rand_token(rng,2,12)},L={_rand_token(rng,2,12)},"
            f"street={_val_for_attr(rng,'street')},postalCode={_val_for_attr(rng,'postalCode')},"
            f"O={_rand_org(rng)},OU={_rand_ou(rng)},CN={_rand_cn(rng)}"
        )
    elif mode == 3:
        # Domain Components with CN
        domain = _rand_domain(rng)
        dcs = ",".join(f"DC={part}" for part in domain.split('.') if part)
        dn = f"{dcs},O={_rand_org(rng)},CN={_rand_cn(rng)}"
    else:
        # Fully random composed DN
        dn = _build_dn(rng)

    # Ensure ASCII and safe characters only (already ensured), and append NUL terminator
    dn_bytes = dn.encode('ascii', errors='ignore')
    # Guarantee non-empty and within limit
    if not dn_bytes:
        dn_bytes = b"CN=example"
    if len(dn_bytes) > 4095:
        dn_bytes = dn_bytes[:4095]
    return dn_bytes + b"\x00"

import random
import ipaddress

# Generates valid IP address strings for mbedtls_x509_crt_parse_cn_inet_pton
# FUZZ_PARAM_STR in the stub is used as the candidate CN string; to exercise
# both success and failure paths, we sometimes return invalid strings, but the
# guidance asks for likely valid inputs. We'll bias towards valid IPv4/IPv6,
# while still varying edge cases (compressed IPv6, IPv4-mapped IPv6, leading
# zeros, max/min values). Output is a bytes buffer containing the ASCII string.

MAX_LEN = 4096


def _rand_ipv4(r: random.Random) -> str:
    # Generate IPv4 dotted-quad, including interesting edge octets
    choices = [0, 1, 127, 128, 169, 172, 192, 223, 224, 239, 255]
    def octet():
        if r.random() < 0.6:
            return r.randint(0, 255)
        return r.choice(choices)
    parts = [octet(), octet(), octet(), octet()]
    # Occasionally include leading zeros in octets (still valid decimal)
    if r.random() < 0.3:
        fmt = lambda v: ("%d" % v) if r.random() < 0.5 else ("%02d" % v)
    else:
        fmt = lambda v: "%d" % v
    return ".".join(fmt(p) for p in parts)


def _rand_ipv6(r: random.Random) -> str:
    # Build various valid IPv6 textual forms
    # Strategies: fully expanded, compressed, IPv4-embedded, IPv4-mapped, link-local with zone id
    strat = r.random()
    # Generate a random IPv6 address object then format with different compressions
    addr_int = r.getrandbits(128)
    ip6 = ipaddress.IPv6Address(addr_int)

    if strat < 0.25:
        # fully expanded 8 groups
        hextets = [(addr_int >> (16*(7-i))) & 0xFFFF for i in range(8)]
        return ":".join(f"{h:04x}" for h in hextets)
    elif strat < 0.5:
        # compressed via ipaddress (short form)
        return ip6.compressed
    elif strat < 0.75:
        # IPv4-mapped or embedded: ::ffff:IPv4 or mixed form
        # Ensure mapped prefix
        v4 = ipaddress.IPv4Address(r.getrandbits(32))
        if r.random() < 0.7:
            return f"::ffff:{v4.compressed}"
        else:
            # Mixed form: xxxx:xxxx:xxxx:xxxx:xxxx:xxxx:d.d.d.d
            hextets = [f"{r.getrandbits(16):x}" for _ in range(6)]
            return ":".join(hextets) + ":" + v4.compressed
    else:
        # link-local with zone id sometimes: fe80::1%eth0 (zone id may be ignored by parser, but include plain fe80::1 mostly)
        base = "fe80::1"
        if r.random() < 0.3:
            zid = r.choice(["eth0", "en0", "1"])  # typical examples
            return f"{base}%{zid}"
        return base


def _rand_invalid(r: random.Random) -> str:
    # Some strings that are likely invalid as IPs but still plausible CNs
    samples = [
        "not.an.ip",
        "999.999.999.999",
        "1.2.3",
        "1.2.3.4.5",
        "2001:::1",
        "g001:db8::1",
        "::ffff:256.0.0.1",
        "",
        "localhost",
    ]
    # Also create a long random hostname-like string sometimes
    if r.random() < 0.3:
        labels = ["".join(r.choice("abcdefghijklmnopqrstuvwxyz0123456789") for _ in range(r.randint(1, 10))) for _ in range(r.randint(2, 4))]
        samples.append(".".join(labels))
    return r.choice(samples)


def generate(seed: int) -> bytes:
    r = random.Random(seed)
    # Choose type: favor valid inputs (~85%) to exercise success paths; include IPv4 and IPv6
    t = r.random()
    if t < 0.45:
        s = _rand_ipv4(r)
    elif t < 0.85:
        s = _rand_ipv6(r)
    else:
        s = _rand_invalid(r)

    b = s.encode("ascii", errors="strict")
    if len(b) > MAX_LEN:
        b = b[:MAX_LEN]
    return b

import random
import struct
import time
from typing import List

# Generate a minimal but valid-ish DER-encoded X.509 CRL.
# We focus on RFC 5280 structure:
# CertificateList ::= SEQUENCE {
#   tbsCertList          TBSCertList,
#   signatureAlgorithm   AlgorithmIdentifier,
#   signatureValue       BIT STRING }
# TBSCertList ::= SEQUENCE {
#   version              Version OPTIONAL,  -- v2(1)
#   signature            AlgorithmIdentifier,
#   issuer               Name,
#   thisUpdate           Time,
#   nextUpdate           Time OPTIONAL,
#   revokedCertificates  SEQUENCE OF SEQUENCE { userCertificate INTEGER, revocationDate Time, crlEntryExtensions [0] ... } OPTIONAL,
#   crlExtensions   [0]  Extensions OPTIONAL }
# We keep it simple: v2, sha256WithRSAEncryption OID (1.2.840.113549.1.1.11), issuer CN, UTCTime times, optional empty revoked list.

# DER helpers

def der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    # long form
    out = []
    while length > 0:
        out.append(length & 0xFF)
        length >>= 8
    out.reverse()
    return bytes([0x80 | len(out)]) + bytes(out)


def der_tlv(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + der_len(len(content)) + content


def der_sequence(contents: List[bytes]) -> bytes:
    content = b"".join(contents)
    return der_tlv(0x30, content)  # UNIVERSAL SEQUENCE, constructed


def der_oid(oid_nums: List[int]) -> bytes:
    # First two numbers packed as 40*x + y
    if len(oid_nums) < 2:
        raise ValueError("OID must have at least two arcs")
    first = 40 * oid_nums[0] + oid_nums[1]
    encoded = [first]
    for v in oid_nums[2:]:
        # base-128 with MSB continuation
        stack = [v & 0x7F]
        v >>= 7
        while v:
            stack.append(0x80 | (v & 0x7F))
            v >>= 7
        encoded.extend(reversed(stack))
    return der_tlv(0x06, bytes(encoded))


def der_null() -> bytes:
    return der_tlv(0x05, b"")


def der_printable_string(s: str) -> bytes:
    data = s.encode('ascii', 'ignore')
    return der_tlv(0x13, data)  # PrintableString


def der_utf8_string(s: str) -> bytes:
    return der_tlv(0x0C, s.encode('utf-8'))


def der_set(contents: List[bytes]) -> bytes:
    content = b"".join(contents)
    return der_tlv(0x31, content)  # SET (constructed)


def der_integer(i: int) -> bytes:
    if i == 0:
        content = b"\x00"
    else:
        # big-endian two's complement minimal
        neg = i < 0
        v = -i if neg else i
        b = bytearray()
        while v:
            b.append(v & 0xFF)
            v >>= 8
        b = bytes(reversed(b)) or b"\x00"
        if not neg:
            if b[0] & 0x80:
                b = b"\x00" + b
            content = b
        else:
            # Not needed here; we only generate positive
            raise ValueError("negative INTEGER not supported here")
    return der_tlv(0x02, content)


def der_bit_string(bits: bytes, unused_bits: int = 0) -> bytes:
    return der_tlv(0x03, bytes([unused_bits]) + bits)


def der_utctime(t: time.struct_time) -> bytes:
    # YYMMDDhhmmssZ
    year = t.tm_year % 100
    s = f"{year:02d}{t.tm_mon:02d}{t.tm_mday:02d}{t.tm_hour:02d}{t.tm_min:02d}{t.tm_sec:02d}Z"
    return der_tlv(0x17, s.encode('ascii'))


def algorithm_identifier_sha256_with_rsa() -> bytes:
    # 1.2.840.113549.1.1.11 with NULL params
    return der_sequence([der_oid([1,2,840,113549,1,1,11]), der_null()])


def x509_name_cn(common_name: str) -> bytes:
    # Name ::= SEQUENCE of RDNs; each RDN SET of AttributeTypeAndValue (OID, value)
    # Use OID for commonName: 2.5.4.3
    atv = der_sequence([der_oid([2,5,4,3]), der_utf8_string(common_name)])
    rdn = der_set([atv])
    return der_sequence([rdn])


def crl_time_pair(now: float, include_next_update: bool) -> List[bytes]:
    t_now = time.gmtime(now)
    # nextUpdate: add between 1 hour and 30 days
    delta = 3600 if not include_next_update else 3600
    return [der_utctime(t_now)] + ([der_utctime(time.gmtime(now + delta))] if include_next_update else [])


def random_serial(rng: random.Random) -> int:
    # Up to 20 bytes as per RFC max for cert serials; CRL entry serials are certificate serials
    nbytes = rng.randint(1, 20)
    # Ensure first byte not 0x00 for minimal encoding; but der_integer handles prefixing 0x00 as needed
    value = 0
    for _ in range(nbytes):
        value = (value << 8) | rng.randrange(0, 256)
    # Ensure non-zero
    if value == 0:
        value = 1
    return value


def revoked_cert_entry(rng: random.Random, when: float) -> bytes:
    serial = random_serial(rng)
    rev_time = der_utctime(time.gmtime(when))
    return der_sequence([der_integer(serial), rev_time])


def build_tbs_crl(rng: random.Random) -> bytes:
    parts: List[bytes] = []
    # version v2 (value 1) OPTIONAL; include it for flexibility
    parts.append(der_integer(1))
    # signature AlgorithmIdentifier
    parts.append(algorithm_identifier_sha256_with_rsa())
    # issuer Name
    cn_variants = [
        "Test CA",
        "Mbed TLS Test CA",
        "Example Org CA",
        "Fuzz-CA",
    ]
    issuer = x509_name_cn(rng.choice(cn_variants))
    parts.append(issuer)
    # thisUpdate and optional nextUpdate
    include_next = rng.choice([True, False])
    now = time.time()
    parts.extend(crl_time_pair(now, include_next))
    # Optional revokedCertificates
    count = rng.choice([0, 0, 1, 2])  # often empty; sometimes a few entries
    if count > 0:
        # Create entries spread in past days
        entries = []
        base = now - 86400 * rng.randint(1, 365)
        for i in range(count):
            entries.append(revoked_cert_entry(rng, base + i * 3600))
        parts.append(der_sequence(entries))
    # Optional crlExtensions [0] EXPLICIT Extensions: we omit for simplicity (still valid)
    return der_sequence(parts)


def build_crl(rng: random.Random) -> bytes:
    tbs = build_tbs_crl(rng)
    sig_alg = algorithm_identifier_sha256_with_rsa()
    # signatureValue is BIT STRING; we provide dummy bytes as content. Validator typically doesn't verify signature during parse.
    # Use a random length between 64 and 256 bytes.
    sig_len = rng.randint(64, 256)
    sig_bytes = bytes(rng.getrandbits(8) for _ in range(sig_len))
    sig = der_bit_string(sig_bytes, unused_bits=0)
    return der_sequence([tbs, sig_alg, sig])


def pem_wrap(der: bytes, line_len: int = 64) -> bytes:
    import base64
    b64 = base64.b64encode(der).decode('ascii')
    lines = [b64[i:i+line_len] for i in range(0, len(b64), line_len)]
    pem = "-----BEGIN X509 CRL-----\n" + "\n".join(lines) + "\n-----END X509 CRL-----\n"
    return pem.encode('ascii')


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    der = build_crl(rng)
    # Occasionally return PEM with terminating NUL to exercise parse() stub path including NUL sizing logic.
    as_pem = rng.random() < 0.5
    if as_pem:
        pem = pem_wrap(der)
        # Parser in mbedtls_x509_crl_parse for PEM expects NUL; the fuzzer may add or not.
        # We return without extra NUL here; the stub may append one randomly. Keep within size limits.
        return pem[:4096]
    else:
        return der[:4096]

import random
import base64
import textwrap
from typing import List

def _rand_datetime(rng: random.Random):
    # Return a tuple (YYYYMMDDhhmmssZ) as bytes for UTC time in ASN.1 UTCTime (YY) or GeneralizedTime
    year = rng.randint(2000, 2035)
    mon = rng.randint(1, 12)
    day = rng.randint(1, 28)
    hour = rng.randint(0, 23)
    minute = rng.randint(0, 59)
    second = rng.randint(0, 59)
    # For CRL, RFC 5280 allows UTCTime for years < 2050, so use YY format
    yy = year % 100
    s = f"{yy:02d}{mon:02d}{day:02d}{hour:02d}{minute:02d}{second:02d}Z"
    return s.encode('ascii')

# Minimal DER writer helpers
class Der:
    @staticmethod
    def len_bytes(length: int) -> bytes:
        if length < 0x80:
            return bytes([length])
        out = []
        while length > 0:
            out.append(length & 0xFF)
            length >>= 8
        out = bytes(reversed(out))
        return bytes([0x80 | len(out)]) + out

    @staticmethod
    def tlv(tag: int, val: bytes) -> bytes:
        return bytes([tag]) + Der.len_bytes(len(val)) + val

    @staticmethod
    def seq(contents: List[bytes]) -> bytes:
        body = b"".join(contents)
        return Der.tlv(0x30, body)

    @staticmethod
    def int_from_bytes(b: bytes) -> bytes:
        # Ensure positive INTEGER with minimal encoding
        if len(b) == 0:
            b = b"\x00"
        # strip leading zeros
        i = 0
        while i + 1 < len(b) and b[i] == 0:
            i += 1
        b = b[i:]
        if b[0] & 0x80:
            b = b"\x00" + b
        return Der.tlv(0x02, b)

    @staticmethod
    def null() -> bytes:
        return Der.tlv(0x05, b"")

    @staticmethod
    def oid(oid: str) -> bytes:
        parts = [int(x) for x in oid.split('.')]
        if len(parts) < 2:
            raise ValueError("OID too short")
        first = 40 * parts[0] + parts[1]
        encoded = [first]
        for p in parts[2:]:
            if p == 0:
                encoded.append(0)
                continue
            stack = []
            while p > 0:
                stack.append(0x80 | (p & 0x7F))
                p >>= 7
            stack[0] &= 0x7F
            encoded.extend(reversed(stack))
        return Der.tlv(0x06, bytes(encoded))

    @staticmethod
    def bit_string(bits: bytes, unused_bits: int = 0) -> bytes:
        return Der.tlv(0x03, bytes([unused_bits]) + bits)

    @staticmethod
    def octet_string(b: bytes) -> bytes:
        return Der.tlv(0x04, b)

    @staticmethod
    def utc_time(t: bytes) -> bytes:
        return Der.tlv(0x17, t)

    @staticmethod
    def constructed_context(tag: int, inner: bytes) -> bytes:
        # context-specific constructed tag: 0xA0 | tag
        return Der.tlv(0xA0 | (tag & 0x1F), inner)

    @staticmethod
    def set(contents: List[bytes]) -> bytes:
        return Der.tlv(0x31, b"".join(contents))

# Build a small but valid X.509 v2 CRL (unsigned with NULL signature value but valid DER structure)
# Many parsers accept structure even if signature doesn't verify; for fuzzing entry, we want a syntactically valid CRL.

def _random_bigint(rng: random.Random, min_bytes=1, max_bytes=20) -> bytes:
    n = rng.randint(min_bytes, max_bytes)
    b = bytearray(rng.getrandbits(8) for _ in range(n))
    # Ensure non-zero
    if all(x == 0 for x in b):
        b[0] = 1
    return bytes(b)

def _name_cn(rng: random.Random, cn: str) -> bytes:
    # Name ::= SEQUENCE OF RDN; RDN ::= SET OF AttributeTypeAndValue
    # AttributeTypeAndValue ::= SEQUENCE { type OID, value DirectoryString }
    # Use commonName OID 2.5.4.3 and PrintableString tag 0x13 for simplicity
    atv = Der.seq([
        Der.oid("2.5.4.3"),
        Der.tlv(0x13, cn.encode('ascii', 'ignore')[:64] or b"CN")
    ])
    rdn = Der.set([atv])
    name = Der.seq([rdn])
    return name

def _algo_sha256WithRSA() -> bytes:
    # AlgorithmIdentifier for sha256WithRSAEncryption: 1.2.840.113549.1.1.11 with NULL params
    return Der.seq([Der.oid("1.2.840.113549.1.1.11"), Der.null()])

def _make_tbs_crl(rng: random.Random) -> bytes:
    # TBSCertList ::= SEQUENCE {
    #  version [0] EXPLICIT Version DEFAULT v1,  -- we'll set v2 (value 1)
    #  signature AlgorithmIdentifier,
    #  issuer Name,
    #  thisUpdate Time,
    #  nextUpdate Time OPTIONAL,
    #  revokedCertificates SEQUENCE OF SEQUENCE { userCertificate INTEGER, revocationDate Time, crlEntryExtensions OPTIONAL } OPTIONAL,
    #  crlExtensions [0] EXPLICIT Extensions OPTIONAL }

    version = Der.constructed_context(0, Der.int_from_bytes(b"\x01"))  # v2
    signature = _algo_sha256WithRSA()
    issuer = _name_cn(rng, "FUZZ-CA-" + str(rng.randint(1, 1_000_000)))
    this_update = Der.utc_time(_rand_datetime(rng))
    next_update = Der.utc_time(_rand_datetime(rng))

    revoked_certs = []
    # Generate 0..3 entries
    for _ in range(rng.randint(0, 3)):
        serial = Der.int_from_bytes(_random_bigint(rng))
        rev_date = Der.utc_time(_rand_datetime(rng))
        entry = Der.seq([serial, rev_date])
        revoked_certs.append(entry)
    revoked_seq = Der.seq(revoked_certs) if revoked_certs else b""  # optional

    # crlExtensions: include basicConstraints-like dummy extension to exercise parser expecting Extensions
    # Use CRLNumber (2.5.29.20) with small INTEGER inside Octet String
    crl_number_ext = Der.seq([
        Der.oid("2.5.29.20"),
        # non-critical, omit BOOLEAN
        Der.octet_string(Der.int_from_bytes(_random_bigint(rng, 1, 4)))
    ])
    extensions = Der.seq([crl_number_ext])
    crl_exts = Der.constructed_context(0, extensions)

    parts = [version, signature, issuer, this_update, next_update]
    if revoked_seq:
        parts.append(revoked_seq)
    parts.append(crl_exts)
    return Der.seq(parts)

def _make_crl_der(rng: random.Random) -> bytes:
    tbs = _make_tbs_crl(rng)
    sig_alg = _algo_sha256WithRSA()
    # SignatureValue is a BIT STRING; we provide a short dummy bit string (all zeros) - syntactically valid
    sig_bits = b"\x00" * rng.randint(8, 32)
    sig_val = Der.bit_string(sig_bits, 0)
    crl = Der.seq([tbs, sig_alg, sig_val])
    return crl

def _pem_wrap(label: str, der: bytes) -> bytes:
    b64 = base64.b64encode(der).decode('ascii')
    lines = "\n".join(textwrap.wrap(b64, 64))
    return (f"-----BEGIN {label}-----\n{lines}\n-----END {label}-----\n").encode('ascii')

def _maybe_chain_multiple_pems(rng: random.Random, single_pem: bytes) -> bytes:
    # Optionally concatenate multiple CRLs to test multi-PEM handling
    count = 1 if rng.random() < 0.6 else rng.randint(2, 4)
    return b"".join(single_pem if i == 0 else _pem_wrap("X509 CRL", _make_crl_der(rng)) for i in range(count))

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    der = _make_crl_der(rng)
    pem = _pem_wrap("X509 CRL", der)
    out = _maybe_chain_multiple_pems(rng, pem)
    # Keep under 4096 bytes
    return out[:4096]

import random
import struct
import time
from typing import List

# We need to generate a file buffer for a DER-encoded X.509 CRL.
# The fuzzer stub calls mbedtls_x509_crl_parse_file(chain, path) where path points to
# a file containing PEM or DER. We'll generate a valid DER CRL (preferably minimal)
# and return its bytes. Keep size <= 4096.
#
# DER encoding helpers for ASN.1 structures needed for a minimal CRL (RFC 5280):
# CertificateList ::= SEQUENCE {
#   tbsCertList          TBSCertList,
#   signatureAlgorithm   AlgorithmIdentifier,
#   signatureValue       BIT STRING
# }
# TBSCertList ::= SEQUENCE {
#   version              Version OPTIONAL,  -- v2(1) for v2 CRL
#   signature            AlgorithmIdentifier,
#   issuer               Name,
#   thisUpdate           Time,
#   nextUpdate           Time OPTIONAL,
#   revokedCertificates  SEQUENCE OF SEQUENCE { userCertificate, revocationDate, crlEntryExtensions OPTIONAL } OPTIONAL,
#   crlExtensions        [0] EXPLICIT Extensions OPTIONAL
# }
# We'll build a minimal but valid v2 CRL signed with sha256WithRSAEncryption OID 1.2.840.113549.1.1.11.
# The signature bits will be dummy zeros (valid DER, not cryptographically valid, but parsers accept structure).

# ASN.1 tag constants
TAG_SEQUENCE = 0x30
TAG_INTEGER = 0x02
TAG_BIT_STRING = 0x03
TAG_OCTET_STRING = 0x04
TAG_NULL = 0x05
TAG_OBJECT_ID = 0x06
TAG_UTC_TIME = 0x17
TAG_GENERALIZED_TIME = 0x18
TAG_SET = 0x31
TAG_PRINTABLE_STRING = 0x13
TAG_UTF8_STRING = 0x0C
TAG_CONTEXT_0 = 0xA0  # [0] explicit


def der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    s = []
    while length > 0:
        s.append(length & 0xFF)
        length >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)


def der_tlv(tag: int, value: bytes) -> bytes:
    return bytes([tag]) + der_len(len(value)) + value


def der_oid_from_arcs(arcs: List[int]) -> bytes:
    assert len(arcs) >= 2
    first = 40 * arcs[0] + arcs[1]
    out = [first]
    for a in arcs[2:]:
        # base-128 varint
        stack = [a & 0x7F]
        a >>= 7
        while a:
            stack.append(0x80 | (a & 0x7F))
            a >>= 7
        out.extend(reversed(stack))
    return der_tlv(TAG_OBJECT_ID, bytes(out))


def der_null() -> bytes:
    return der_tlv(TAG_NULL, b"")


def der_algorithm_identifier_sha256WithRSA() -> bytes:
    # OID 1.2.840.113549.1.1.11, NULL params
    oid = der_oid_from_arcs([1, 2, 840, 113549, 1, 1, 11])
    return der_tlv(TAG_SEQUENCE, oid + der_null())


def der_integer(n: int) -> bytes:
    # encode non-negative integer
    if n == 0:
        content = b"\x00"
    else:
        bts = bytearray()
        while n > 0:
            bts.append(n & 0xFF)
            n >>= 8
        bts.reverse()
        # ensure first bit not interpreted as sign
        if bts[0] & 0x80:
            bts = bytearray([0]) + bts
        content = bytes(bts)
    return der_tlv(TAG_INTEGER, content)


def der_printable_string(s: str) -> bytes:
    return der_tlv(TAG_PRINTABLE_STRING, s.encode('ascii'))


def der_utf8_string(s: str) -> bytes:
    return der_tlv(TAG_UTF8_STRING, s.encode('utf-8'))


def der_set(content: bytes) -> bytes:
    return der_tlv(TAG_SET, content)


def der_sequence(content: bytes) -> bytes:
    return der_tlv(TAG_SEQUENCE, content)


def encode_rdn(oid_arcs: List[int], value: str, printable: bool = True) -> bytes:
    # AttributeTypeAndValue ::= SEQUENCE { type OBJECT IDENTIFIER, value ANY }
    atv = der_sequence(der_oid_from_arcs(oid_arcs) + (der_printable_string(value) if printable else der_utf8_string(value)))
    # RelativeDistinguishedName ::= SET OF AttributeTypeAndValue
    return der_set(atv)


def encode_name_cn(common_name: str) -> bytes:
    # Name ::= SEQUENCE OF RDNs
    # Use CN (2.5.4.3)
    rdn = encode_rdn([2, 5, 4, 3], common_name, printable=False)
    return der_sequence(rdn)


def encode_time(t: time.struct_time, use_generalized: bool) -> bytes:
    if use_generalized:
        # YYYYMMDDhhmmssZ
        s = time.strftime("%Y%m%d%H%M%SZ", t)
        return der_tlv(TAG_GENERALIZED_TIME, s.encode('ascii'))
    else:
        # YYMMDDhhmmssZ (UTC time)
        s = time.strftime("%y%m%d%H%M%SZ", t)
        return der_tlv(TAG_UTC_TIME, s.encode('ascii'))


def encode_revoked_entry(serial_int: int, rev_time: time.struct_time) -> bytes:
    user_cert = der_integer(serial_int)
    revocation_date = encode_time(rev_time, use_generalized=(rev_time.tm_year >= 2050 or rev_time.tm_year < 1950))
    return der_sequence(user_cert + revocation_date)


def build_tbs_crl(issuer_cn: str, now: float, include_next_update: bool, num_revoked: int) -> bytes:
    # version v2 = 1 (optional, but include to be explicit)
    version = der_integer(1)
    signature = der_algorithm_identifier_sha256WithRSA()
    issuer = encode_name_cn(issuer_cn)

    t_now = time.gmtime(now)
    this_update = encode_time(t_now, use_generalized=(t_now.tm_year >= 2050 or t_now.tm_year < 1950))

    next_update = b""
    if include_next_update:
        t_next = time.gmtime(now + 86400)
        next_update = encode_time(t_next, use_generalized=(t_next.tm_year >= 2050 or t_next.tm_year < 1950))

    revoked_seq = b""
    if num_revoked > 0:
        entries = []
        base_serial = 1000
        for i in range(num_revoked):
            rt = time.gmtime(now - (i + 1) * 3600)
            entries.append(encode_revoked_entry(base_serial + i, rt))
        revoked_seq = der_sequence(b"".join(entries))

    tbs = der_sequence(version + signature + issuer + this_update + next_update + revoked_seq)
    return tbs


def bit_string_zeroes(nbytes: int) -> bytes:
    # BIT STRING: first byte is number of unused bits (0), then payload
    return der_tlv(TAG_BIT_STRING, b"\x00" + (b"\x00" * nbytes))


def build_crl(seed: int) -> bytes:
    rnd = random.Random(seed)
    issuer_cn = rnd.choice([
        "Test CRL Issuer",
        "Example CA",
        "Mbed TLS Test CA",
        "Acme Root CA",
    ])
    now = time.time() - rnd.randint(0, 30) * 86400
    include_next = rnd.choice([True, False])
    num_revoked = rnd.randint(0, 3)

    tbs = build_tbs_crl(issuer_cn, now, include_next, num_revoked)
    sig_alg = der_algorithm_identifier_sha256WithRSA()
    # Signature value length: choose small but plausible length; DER allows any bit string.
    sig_bits = bit_string_zeroes(64)  # 512-bit dummy signature

    crl = der_sequence(tbs + sig_alg + sig_bits)
    return crl


def generate(seed: int) -> bytes:
    # Produce a valid DER-encoded CRL buffer
    der = build_crl(seed)
    # Ensure size limit
    if len(der) > 4096:
        # Fallback to minimal variant
        der = build_tbs_crl("Mbed TLS Test CA", time.time(), True, 0)
        der = der_sequence(der + der_algorithm_identifier_sha256WithRSA() + bit_string_zeroes(32))
    return der

import random
import secrets
import string
from typing import List

# Data type: URI string for SAN uniformResourceIdentifier entries.
# The fuzzer stubs will use FUZZ_PARAM_STR() to fetch this buffer as a string.
# We therefore generate a valid, reasonably varied URI that fits typical SAN URI expectations.
# Goals:
# - Produce syntactically valid URIs with different schemes (http, https, ftp, mailto, urn, ip-based, custom schemes).
# - Cover userinfo, ports, IPv4/IPv6 hosts, paths, queries, fragments.
# - Keep total length <= 4096.
# - Seeded randomness.

SCHEMES = [
    "http", "https", "ftp", "ftps", "ws", "wss",
    "mailto", "urn", "sip", "tel", "data", "ssh",
    "custom+v1"
]

TLDS = [
    "com", "org", "net", "io", "dev", "example", "local"
]

USER_CHARS = string.ascii_letters + string.digits + "._-"
HOST_LABEL_CHARS = string.ascii_lowercase + string.digits + "-"
PATH_CHARS = string.ascii_letters + string.digits + "-._~!$&'()*+,;=:@"
QUERY_CHARS = PATH_CHARS + "/?"
FRAG_CHARS = QUERY_CHARS
URN_NAMESPACES = ["uuid", "oid", "isbn", "example"]


def rand_choice(rng: random.Random, seq: List[str]):
    return seq[rng.randrange(len(seq))]


def gen_domain(rng: random.Random) -> str:
    # Generate a DNS name with 2-4 labels
    n_labels = rng.randint(2, 4)
    labels = []
    for i in range(n_labels - 1):
        ln = rng.randint(1, 10)
        # ensure label doesn't start or end with '-'
        s = ''.join(rng.choice(HOST_LABEL_CHARS) for _ in range(ln))
        if s[0] == '-':
            s = 'a' + s[1:]
        if s[-1] == '-':
            s = s[:-1] + 'b'
        labels.append(s)
    labels.append(rand_choice(rng, TLDS))
    return '.'.join(labels)


def gen_ipv4(rng: random.Random) -> str:
    return '.'.join(str(rng.randint(1, 255)) for _ in range(4))


def gen_ipv6(rng: random.Random) -> str:
    # Simplified IPv6 generation with optional compression
    hextets = [f"{rng.randrange(0, 1<<16):x}" for _ in range(8)]
    if rng.random() < 0.5:
        # compress a run of 0s
        # find runs of '0'
        runs = []
        i = 0
        while i < 8:
            if hextets[i] == '0':
                j = i
                while j < 8 and hextets[j] == '0':
                    j += 1
                runs.append((i, j))
                i = j
            else:
                i += 1
        if runs:
            start, end = rand_choice(rng, runs)
            hextets = hextets[:start] + [''] + hextets[end:]
            # build with '::'
            left = ':'.join(hextets[:start])
            right = ':'.join(hextets[start+1:])
            if left and right:
                return left + '::' + right
            elif left:
                return left + '::'
            elif right:
                return '::' + right
            else:
                return '::'
    return ':'.join(hextets)


def gen_userinfo(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    user = ''.join(rng.choice(USER_CHARS) for _ in range(rng.randint(3, 10)))
    if rng.random() < 0.5:
        pwd = ''.join(rng.choice(USER_CHARS) for _ in range(rng.randint(3, 8)))
        return f"{user}:{pwd}@"
    return f"{user}@"


def gen_port(rng: random.Random) -> str:
    if rng.random() < 0.6:
        return ''
    return f":{rng.choice([80, 443, 21, 22, 25, 143, 993, rng.randint(1024, 65535)])}"


def gen_path(rng: random.Random) -> str:
    # 0 to 4 segments
    segs = []
    n = rng.randint(0, 4)
    for _ in range(n):
        ln = rng.randint(0, 12)
        if ln == 0:
            segs.append('')
        else:
            segs.append(''.join(rng.choice(PATH_CHARS) for _ in range(ln)))
    return '/' + '/'.join(segs) if segs else ''


def gen_query(rng: random.Random) -> str:
    if rng.random() < 0.5:
        return ''
    pairs = []
    for _ in range(rng.randint(1, 3)):
        k = ''.join(rng.choice(QUERY_CHARS) for _ in range(rng.randint(1, 8)))
        v = ''.join(rng.choice(QUERY_CHARS) for _ in range(rng.randint(0, 10)))
        pairs.append(f"{k}={v}")
    return '?' + '&'.join(pairs)


def gen_fragment(rng: random.Random) -> str:
    if rng.random() < 0.3:
        return ''
    frag = ''.join(rng.choice(FRAG_CHARS) for _ in range(rng.randint(1, 10)))
    return '#' + frag


def gen_mailto(rng: random.Random) -> str:
    local = ''.join(rng.choice(USER_CHARS) for _ in range(rng.randint(3, 10)))
    domain = gen_domain(rng)
    params = gen_query(rng)
    return f"mailto:{local}@{domain}{params}"


def gen_urn(rng: random.Random) -> str:
    ns = rand_choice(rng, URN_NAMESPACES)
    if ns == 'uuid':
        # Generate RFC4122-like UUID
        def rbytes(n):
            return secrets.token_bytes(n)
        b = bytearray(rbytes(16))
        b[6] = (b[6] & 0x0F) | 0x40
        b[8] = (b[8] & 0x3F) | 0x80
        hexs = b.hex()
        uuid = f"{hexs[0:8]}-{hexs[8:12]}-{hexs[12:16]}-{hexs[16:20]}-{hexs[20:32]}"
        return f"urn:uuid:{uuid}"
    elif ns == 'oid':
        # Common OID prefix with a few arcs
        arcs = ["1", "2"][rng.randrange(2)]
        # Append 3-6 arcs between 1..10000
        for _ in range(rng.randint(3, 6)):
            arcs += "." + str(rng.randint(1, 10000))
        return f"urn:oid:{arcs}"
    else:
        nid = ns
        nss = ''.join(rng.choice(string.ascii_lowercase + string.digits + "-._:") for _ in range(rng.randint(4, 20)))
        return f"urn:{nid}:{nss}"


def gen_data_uri(rng: random.Random) -> str:
    # Small, valid data URI
    mediatype = rand_choice(rng, ["text/plain", "text/html", "application/octet-stream", "image/png"]) \
        + (";charset=UTF-8" if rng.random() < 0.5 else "")
    if rng.random() < 0.6:
        # base64 variant
        raw_len = rng.randint(3, 24)
        raw = secrets.token_bytes(raw_len)
        import base64
        b64 = base64.b64encode(raw).decode('ascii')
        return f"data:{mediatype};base64,{b64}"
    else:
        # percent-encoded
        payload = ''.join(rng.choice(string.ascii_letters + string.digits + "-._~!$&'()*+,;=:@/") for _ in range(rng.randint(3, 30)))
        return f"data:{mediatype},{payload}"


def gen_authority(rng: random.Random) -> str:
    t = rng.random()
    if t < 0.6:
        host = gen_domain(rng)
    elif t < 0.8:
        host = gen_ipv4(rng)
    else:
        host = f"[{gen_ipv6(rng)}]"
    return gen_userinfo(rng) + host + gen_port(rng)


def gen_hier_uri(rng: random.Random, scheme: str) -> str:
    authority = gen_authority(rng)
    path = gen_path(rng)
    query = gen_query(rng)
    frag = gen_fragment(rng)
    return f"{scheme}://{authority}{path}{query}{frag}"


def build_uri(rng: random.Random) -> str:
    scheme = rand_choice(rng, SCHEMES)
    if scheme == 'mailto':
        return gen_mailto(rng)
    if scheme == 'urn':
        return gen_urn(rng)
    if scheme == 'data':
        return gen_data_uri(rng)
    # Hierarchical schemes
    return gen_hier_uri(rng, scheme)


def clamp_size(b: bytes, limit: int = 4096) -> bytes:
    if len(b) <= limit:
        return b
    return b[:limit]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Bias towards HTTPS/DNS-like hostnames sometimes, to match common SAN use:
    if rng.random() < 0.25:
        uri = gen_hier_uri(rng, 'https')
    else:
        uri = build_uri(rng)
    b = uri.encode('utf-8', errors='strict')
    return clamp_size(b)

import random
import struct
from typing import List

# Generate a minimal, valid DER-encoded PKCS#7 SignedData (detached) object.
# We build ASN.1 DER for:
# ContentInfo ::= SEQUENCE { contentType OID pkcs7-signedData, content [0] EXPLICIT SignedData }
# SignedData ::= SEQUENCE { version INTEGER(1), digestAlgorithms SET OF AlgorithmIdentifier,
#   encapContentInfo ContentInfo(data, with absent content [0]), certificates [0] IMPLICIT OPTIONAL (omitted),
#   crls [1] IMPLICIT OPTIONAL (omitted), signerInfos SET OF SignerInfo }
# SignerInfo ::= SEQUENCE { version INTEGER(1), issuerAndSerialNumber SEQUENCE { issuer Name (empty RDNSequence), serialNumber INTEGER },
#   digestAlgorithm AlgorithmIdentifier(sha256), authenticatedAttributes [0] IMPLICIT OPTIONAL (omitted),
#   digestEncryptionAlgorithm AlgorithmIdentifier(rsaEncryption with NULL params), signature OCTET STRING }
# For detached signatures, encapContentInfo has contentType=pkcs7-data and absent [0] content.
# This won’t verify (random signature), but it should parse successfully as structure.


def der_len(length: int) -> bytes:
    if length < 0x80:
        return bytes([length])
    # long form
    s = []
    while length > 0:
        s.append(length & 0xFF)
        length >>= 8
    s.reverse()
    return bytes([0x80 | len(s)]) + bytes(s)


def der_tag(tag: int, content: bytes) -> bytes:
    return bytes([tag]) + der_len(len(content)) + content


def der_integer(n: int) -> bytes:
    # Encode non-negative integer
    if n == 0:
        enc = b"\x00"
    else:
        tmp = bytearray()
        while n > 0:
            tmp.insert(0, n & 0xFF)
            n >>= 8
        # Ensure MSB not set
        if tmp[0] & 0x80:
            tmp.insert(0, 0)
        enc = bytes(tmp)
    return der_tag(0x02, enc)


def der_octet_string(b: bytes) -> bytes:
    return der_tag(0x04, b)


def der_null() -> bytes:
    return der_tag(0x05, b"")


def der_oid(oid_bytes: bytes) -> bytes:
    return der_tag(0x06, oid_bytes)


def der_sequence(components: List[bytes]) -> bytes:
    return der_tag(0x30, b"".join(components))


def der_set(components: List[bytes]) -> bytes:
    # SET OF: DER requires elements sorted by canonical order. Our list size is 1 -> already canonical.
    return der_tag(0x31, b"".join(components))


def der_explicit(tag_num: int, inner: bytes) -> bytes:
    # [tag_num] EXPLICIT, universal class context-specific constructed: 0xA0 | tag
    return der_tag(0xA0 + tag_num, inner)


def der_implicit(tag_num: int, inner_tag: int, inner_content: bytes) -> bytes:
    # Replace the tag with context-specific class, keep constructed bit if inner was constructed
    constructed = (inner_tag & 0x20) != 0
    new_tag = 0x80 | (0x20 if constructed else 0) | tag_num
    return der_tag(new_tag, inner_content)


def algo_id_sha256() -> bytes:
    # sha256 OID: 2.16.840.1.101.3.4.2.1 -> bytes: 0x60 0x86 0x48 0x01 0x65 0x03 0x04 0x02 0x01 with DER OID header 0x06
    # First two nodes: 2*40 + 16 = 0x50
    oid = bytes([0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01])
    return der_sequence([der_oid(oid), der_null()])


def algo_id_rsa_encryption() -> bytes:
    # 1.2.840.113549.1.1.1 -> 0x2A 0x86 0x48 0x86 0xF7 0x0D 0x01 0x01 0x01
    oid = bytes([0x2A, 0x86, 0x48, 0x86, 0xF7, 0x0D, 0x01, 0x01, 0x01])
    return der_sequence([der_oid(oid), der_null()])


def oid_pkcs7_signed_data() -> bytes:
    # 1.2.840.113549.1.7.2
    return bytes([0x2A, 0x86, 0x48, 0x86, 0xF7, 0x0D, 0x01, 0x07, 0x02])


def oid_pkcs7_data() -> bytes:
    # 1.2.840.113549.1.7.1
    return bytes([0x2A, 0x86, 0x48, 0x86, 0xF7, 0x0D, 0x01, 0x07, 0x01])


def empty_name_sequence() -> bytes:
    # Name ::= CHOICE { rdnSequence RDNSequence }
    # RDNSequence ::= SEQUENCE OF RelativeDistinguishedName; empty is allowed -> SEQUENCE of length 0
    return der_sequence([])


def random_bytes(rnd: random.Random, n: int) -> bytes:
    return bytes(rnd.getrandbits(8) for _ in range(n))


def build_signed_data(rnd: random.Random) -> bytes:
    # version = 1
    version = der_integer(1)

    # digestAlgorithms = SET OF { sha256 }
    digest_algs = der_set([algo_id_sha256()])

    # encapContentInfo: ContentInfo with contentType=data and absent [0] content (detached)
    eci = der_sequence([
        der_oid(oid_pkcs7_data()),
        # No content ([0] EXPLICIT) to make it detached
    ])

    # signerInfos = SET OF { SignerInfo }
    # Build a single SignerInfo
    si_version = der_integer(1)

    # issuerAndSerialNumber: issuer Name (empty) and serialNumber INTEGER
    serial_val = rnd.randrange(1, 1 << 64)
    issuer_and_serial = der_sequence([
        empty_name_sequence(),
        der_integer(serial_val)
    ])

    # digestAlgorithm: sha256
    digest_alg = algo_id_sha256()

    # digestEncryptionAlgorithm: rsaEncryption with NULL params
    digest_enc_alg = algo_id_rsa_encryption()

    # signature: random bytes (length 64..256)
    sig_len = rnd.randrange(64, 257)
    signature = der_octet_string(random_bytes(rnd, sig_len))

    signer_info = der_sequence([
        si_version,
        issuer_and_serial,
        digest_alg,
        # omit authenticatedAttributes [0]
        digest_enc_alg,
        signature
    ])

    signer_infos = der_set([signer_info])

    signed_data = der_sequence([
        version,
        digest_algs,
        eci,
        # omit certificates [0], crls [1]
        signer_infos
    ])

    # Wrap as [0] EXPLICIT SignedData inside top-level ContentInfo for signedData
    content_info = der_sequence([
        der_oid(oid_pkcs7_signed_data()),
        der_explicit(0, signed_data)
    ])

    return content_info


def maybe_add_cert_placeholder(rnd: random.Random, signed_data_seq: bytes) -> bytes:
    # This helper is not used: PKCS7 parser in Mbed TLS supports at most one cert, but it is optional.
    # We keep minimal object to maximize acceptance.
    return signed_data_seq


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Build a valid minimal PKCS#7 SignedData (detached). Randomize some fields to get variety:
    blob = build_signed_data(rnd)

    # Optionally add benign padding noise by choosing between a few variants (not altering structure): none.
    # Ensure size limit
    if len(blob) > 4096:
        # Extremely unlikely, but truncate signature length and rebuild
        rnd2 = random.Random(seed ^ 0xABCDEF)
        while True:
            blob = build_signed_data(rnd2)
            if len(blob) <= 4096:
                break
    return blob
